const M = `() => {
  const g = (sel) => { const el = document.querySelector(sel); if(!el) return null; const s = getComputedStyle(el);
    return { font: s.fontFamily.split(',')[0].replace(/["']/g,''), size: s.fontSize, weight: s.fontWeight, lh: s.lineHeight, ls: s.letterSpacing, color: s.color, bg: s.backgroundColor, w: Math.round(el.getBoundingClientRect().width) }; };
  const lum = (c) => { const [r,gg,b] = c.match(/\\d+/g).map(Number).map(v=>{v/=255;return v<=0.03928?v/12.92:Math.pow((v+0.055)/1.055,2.4);}); return 0.2126*r+0.7152*gg+0.0722*b; };
  const ratio = (fg,bg) => { try { const a=lum(fg), b=lum(bg); return Math.round(((Math.max(a,b)+0.05)/(Math.min(a,b)+0.05))*100)/100; } catch(e){ return null; } };
  const body = g('body');
  const secs = [...document.querySelectorAll('main > section, body > section')];
  const rhythm = [];
  for (let i=1;i<secs.length && i<10;i++){ const a=secs[i-1].getBoundingClientRect(), b=secs[i].getBoundingClientRect(); }
  const padTop = secs[0] ? getComputedStyle(secs[0]).paddingTop : null;
  const padBot = secs[0] ? getComputedStyle(secs[0]).paddingBottom : null;
  return { url: location.hostname, h1: g('h1'), h2: g('h2'), body, p: g('p'),
    bodyContrast: body ? ratio(body.color, body.bg === 'rgba(0, 0, 0, 0)' ? 'rgb(255,255,255)' : body.bg) : null,
    sectionCount: secs.length, sectionPadTop: padTop, sectionPadBottom: padBot,
    maxTextWidth: document.querySelector('p') ? Math.round(document.querySelector('p').getBoundingClientRect().width) : null,
    viewport: innerWidth };
}`;
const out = [];
await tools.playwright.browser_resize({ width: 1440, height: 900 });
for (const site of ["https://linear.app", "https://stripe.com", "https://anthropic.com", "https://stamen.com"]) {
  try {
    await tools.playwright.browser_navigate({ url: site });
    await tools.playwright.browser_wait_for({ time: 2 });
    const r = await tools.playwright.browser_evaluate({ function: M });
    out.push(r);
  } catch (e) { out.push({ url: site, error: String(e).slice(0, 200) }); }
}
return JSON.stringify(out, null, 1);

